// Probe harness for the Python reference executable.
// Usage:
//   node /tmp/probe.mjs cases.json          # cases.json = [{a: "<json str>", b: "<json str>"}, ...]
//   node /tmp/probe.mjs --argv argvcases.json  # [[".. raw argv .."], ...]
// Prints, per case, exit code + exact stdout + first stderr line. No shell quoting problems.
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test2_executable';
const JS = process.env.JS_ENTRY || '/output/test2.mjs';

const mode = process.argv[2] === '--argv' ? 'argv' : 'ab';
const file = mode === 'argv' ? process.argv[3] : process.argv[2];
const cases = JSON.parse(readFileSync(file, 'utf8'));
const compare = process.env.COMPARE === '1';

function run(cmd, args) {
  const r = spawnSync(cmd, args, { encoding: 'buffer', maxBuffer: 1 << 28 });
  const out = (r.stdout || Buffer.alloc(0)).toString('utf8');
  const err = (r.stderr || Buffer.alloc(0)).toString('utf8');
  return { code: r.status, out, err };
}

function show(label, r) {
  const errLast = r.err.trim().split('\n').filter(l => l.trim()).slice(-1)[0] || '';
  console.log(`  ${label} rc=${r.code} stdout=${JSON.stringify(r.out)}`);
  if (r.code !== 0 && errLast) console.log(`  ${label} stderr(last)=${JSON.stringify(errLast.slice(0, 300))}`);
}

let diffs = 0;
for (const [i, c] of cases.entries()) {
  const argv = mode === 'argv' ? c : ['--a', c.a, '--b', c.b];
  console.log(`[${i}] ${JSON.stringify(argv)}`);
  const py = run(EXE, argv);
  show('PY', py);
  if (compare) {
    const js = run('node', [JS, ...argv]);
    show('JS', js);
    const same = js.out === py.out && js.code === py.code;
    if (!same) { diffs++; console.log('  ***MISMATCH***'); }
  }
}
if (compare) console.log(`\n${diffs} mismatches / ${cases.length} cases`);

