// self-contained: import cases module, run exe directly
import { spawnSync } from 'node:child_process';
const EXE = '/workspace/dataset/test2_executable';
const mod = await import(process.argv[2]);
const cases = mod.default;
for (const [i, c] of cases.entries()) {
  const a = typeof c[0] === 'string' ? c[0] : JSON.stringify(c[0]);
  const b = typeof c[1] === 'string' ? c[1] : JSON.stringify(c[1]);
  const t0 = Date.now();
  const r = spawnSync(EXE, ['--a', a, '--b', b], { encoding: 'buffer', maxBuffer: 1<<28, timeout: 60000 });
  const ms = Date.now() - t0;
  const out = (r.stdout||Buffer.alloc(0)).toString('utf8');
  const err = (r.stderr||Buffer.alloc(0)).toString('utf8');
  const errLines = err.trim().split('\n').filter(l=>l.trim());
  // find the python exception line (last line that looks like Name: msg or has Error)
  let exc = '';
  for (let k = errLines.length-1; k >= 0; k--) {
    if (/^[A-Za-z_][A-Za-z0-9_.]*(Error|Exception|Warning)\b/.test(errLines[k]) || /Error:/.test(errLines[k])) { exc = errLines[k]; break; }
  }
  console.log(`[${i}] A=${JSON.stringify(a)}`);
  console.log(`    B=${JSON.stringify(b)}`);
  console.log(`    rc=${r.status} t=${ms}ms out=${JSON.stringify(out)}${exc?`\n    EXC=${JSON.stringify(exc.slice(0,240))}`:''}`);
}
ZEOF
